const desktopApps=[['projects','Mes projets'],['about','À propos.txt'],['contact','Contact'],['terminal','Terminal'],['bin','Corbeille'],['paint','Paint'],['mines','Démineur'],['settings','Paramètres'],['welcome','Lisez-moi']];
let zIndex=10,activeId=null,selectedIcon=null,audioContext=null,sounds=false;
const openWindows=new Map();
function beep(frequency=550){if(!sounds)return;try{audioContext??=new AudioContext();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=frequency;g.gain.setValueAtTime(.025,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.075);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.08)}catch{}}
desktopApps.forEach(([id,name])=>{const b=document.createElement('button');b.className='desktop-icon';b.innerHTML=icon(apps[id].icon)+`<span>${name}</span>`;b.setAttribute('aria-label',`Ouvrir ${name}`);b.onclick=e=>{selectedIcon?.classList.remove('selected');selectedIcon=b;b.classList.add('selected');if(e.detail===0||matchMedia('(pointer:coarse)').matches)openApp(id)};b.ondblclick=()=>openApp(id);$('#icons').append(b)});
document.querySelectorAll('#start-menu [data-open]').forEach(b=>b.insertAdjacentHTML('afterbegin',icon(apps[b.dataset.open].icon)));
function focusWindow(id){const w=openWindows.get(id);if(!w)return;activeId=id;openWindows.forEach((v,k)=>{v.el.classList.toggle('focused',k===id);v.task.classList.toggle('active',k===id&&!v.minimized)});w.el.style.zIndex=++zIndex}
function focusLast(){const list=[...openWindows].filter(([,v])=>!v.minimized).sort((a,b)=>Number(b[1].el.style.zIndex)-Number(a[1].el.style.zIndex));activeId=null;if(list.length)focusWindow(list[0][0])}
function restore(id){const w=openWindows.get(id);if(!w)return;w.minimized=false;w.el.hidden=false;focusWindow(id)}
function minimize(id){const w=openWindows.get(id);w.minimized=true;w.el.hidden=true;w.task.classList.remove('active');if(activeId===id)focusLast()}
function closeWindow(id){const w=openWindows.get(id);if(!w)return;w.cleanup?.();w.el.remove();w.task.remove();openWindows.delete(id);if(activeId===id)focusLast()}
function maximize(id){const w=openWindows.get(id);w.el.classList.toggle('maximized');const b=w.el.querySelector('[data-control=max]'),max=w.el.classList.contains('maximized');b.textContent=max?'▣':'□';b.setAttribute('aria-label',max?'Restaurer la fenêtre':'Agrandir la fenêtre')}
function openApp(id){closeMenus();if(openWindows.has(id)){restore(id);return}const app=apps[id];if(!app)return;const el=document.createElement('section');el.className='window';el.setAttribute('aria-label',app.title);el.setAttribute('role','region');const offset=(openWindows.size%5)*25;let left=Math.max(220,(innerWidth-app.width)/2+offset),top=id==='welcome'?Math.max(25,(desktop.clientHeight-app.height)/2-15):55+offset;left=Math.max(4,Math.min(left,innerWidth-app.width-8));top=Math.max(4,Math.min(top,desktop.clientHeight-app.height-8));Object.assign(el.style,{width:Math.min(app.width,innerWidth-16)+'px',height:Math.min(app.height,desktop.clientHeight-16)+'px',left:left+'px',top:top+'px'});
el.innerHTML=`<div class="titlebar"><span class="title-name">${icon(app.icon)}${app.title}</span><div class="window-controls"><button data-control="min" aria-label="Réduire la fenêtre">_</button><button data-control="max" aria-label="Agrandir la fenêtre">□</button><button data-control="close" aria-label="Fermer la fenêtre">×</button></div></div><div class="menu-bar"><button data-menu="close"><u>F</u>ichier</button><button data-menu="help"><u>A</u>ide</button></div><div class="window-content"></div><div class="statusbar">Prêt</div>`;
const task=document.createElement('button');task.className='task';task.innerHTML=icon(app.icon)+`<span>${app.title}</span>`;task.setAttribute('aria-label',`Afficher ou réduire ${app.title}`);task.onclick=()=>{const w=openWindows.get(id);if(activeId===id&&!w.minimized)minimize(id);else restore(id)};$('#tasks').append(task);windows.append(el);const state={el,task,minimized:false,cleanup:null,fileActions:[]};openWindows.set(id,state);el.addEventListener('pointerdown',()=>focusWindow(id));el.querySelector('[data-control=min]').onclick=()=>minimize(id);el.querySelector('[data-control=max]').onclick=()=>maximize(id);el.querySelector('[data-control=close]').onclick=()=>closeWindow(id);el.querySelector('[data-menu=close]').onclick=e=>{e.stopPropagation();showFileMenu(id,e.currentTarget)};el.querySelector('[data-menu=help]').onclick=()=>systemMessage('Déplace une fenêtre par sa barre de titre. Utilise les trois boutons pour la réduire, l’agrandir ou la fermer.');
const title=el.querySelector('.titlebar');title.ondblclick=e=>{if(!e.target.closest('button'))maximize(id)};let drag=null;title.addEventListener('pointerdown',e=>{if(e.target.closest('button')||el.classList.contains('maximized')||innerWidth<751)return;drag={x:e.clientX,y:e.clientY,left:el.offsetLeft,top:el.offsetTop};title.setPointerCapture(e.pointerId);e.preventDefault()});title.addEventListener('pointermove',e=>{if(!drag)return;el.style.left=Math.max(0,Math.min(desktop.clientWidth-el.offsetWidth,drag.left+e.clientX-drag.x))+'px';el.style.top=Math.max(0,Math.min(desktop.clientHeight-35,drag.top+e.clientY-drag.y))+'px'});title.addEventListener('pointerup',()=>drag=null);title.addEventListener('pointercancel',()=>drag=null);
renderApp(id,el.querySelector('.window-content'),state);const paintSave=el.querySelector('#paint-save'),mineNew=el.querySelector('.mine-restart');if(paintSave)addMenu(state,'Enregistrer .png',()=>paintSave.click());if(mineNew)addMenu(state,'Nouvelle partie',()=>mineNew.click());focusWindow(id);beep();}
function renderApp(id,content,state){const status=state.el.querySelector('.statusbar');
if(id==='welcome'){content.innerHTML=`<div class="welcome-content"><aside class="welcome-side">${icon('computer')}<strong><small>Portfolio</small>95</strong><small>PERSONAL<br>EDITION</small></aside><div class="welcome-main"><span class="eyebrow">README.TXT / BONJOUR !</span><h1>Bienvenue<br>sur mon bureau.</h1><p>Je suis développeur.<br>Explore mes projets, découvre mon parcours et prends un moment pour jouer.</p><hr><p>Chaque icône ouvre un petit morceau de mon univers.</p><div class="welcome-actions"><button class="primary" data-open="projects">Explorer mes projets</button><button data-open="about">Faire connaissance</button></div><p class="welcome-note">Psst… Paint et le Démineur fonctionnent vraiment.</p></div></div>`;status.textContent='Portfolio 95 · Édition personnelle';}
else if(id==='projects'){content.innerHTML=`<div class="address"><span>Adresse</span><code>C:\\Portfolio\\Projets</code></div><div class="explorer-layout"><aside class="explorer-sidebar"><strong>Mes projets</strong>${icon('folder')}<p>Sélectionne un dossier pour découvrir un projet.</p><p>Les contenus et liens personnels restent à renseigner.</p></aside><div class="explorer-files">${[1,2,3].map(n=>`<button class="file-item" data-open="project${n}">${icon('folder')}<span>Projet 0${n}</span><small>À personnaliser</small></button>`).join('')}<button class="file-item" data-open="readme">${icon('text')}<span>LISEZ-MOI.txt</span></button></div></div>`;status.textContent='4 objets · C:\\Portfolio\\Projets';}
else if(id==='about'){content.innerHTML='<textarea class="notepad" aria-label="Présentation personnelle" spellcheck="false"></textarea>';content.querySelector('textarea').value='À PROPOS DE MOI\n================\n\nJe suis développeur.\n\nCe bureau est mon portfolio personnel : un espace\npour présenter mon travail et les choix derrière mon code.\n\nÀ compléter avec mon parcours, mes compétences\net ce que j’aime construire.\n\nCe texte est éditable, comme dans le Bloc-notes.\nUtilise « Enregistrer » pour le télécharger.';addMenu(state,'Enregistrer',()=>download(content.querySelector('textarea').value,'a-propos.txt','text/plain'));status.textContent='Document local · Modifications non sauvegardées automatiquement';}
else if(id==='readme'){content.innerHTML='<textarea class="notepad" aria-label="Instructions du portfolio" readonly></textarea>';content.querySelector('textarea').value='BIENVENUE DANS MES PROJETS\n=========================\n\nChaque dossier accueillera un vrai projet :\n\n- Le problème à résoudre\n- Mon rôle dans sa réalisation\n- Les technologies et décisions techniques\n- Une démonstration et le code source\n- Les résultats et ce que j’ai appris\n\nLes dossiers actuels sont des emplacements à remplir.\n\nAstuce : essaie la commande « help » dans le terminal.';status.textContent='Lecture seule';}
else if(id.startsWith('project')){content.innerHTML=`<div class="plain-page"><span class="badge">À personnaliser</span><h1>Projet 0${id.slice(-1)}</h1><p>Cet emplacement accueillera l’un de mes projets.</p><h2>Ce qu’il présentera</h2><p>Le contexte, mon rôle, les décisions techniques, les difficultés rencontrées et le résultat.</p><h2>Démo & code source</h2><p>Les liens seront ajoutés avec le vrai projet.</p><button data-open="projects">Retour aux projets</button></div>`;status.textContent='Contenu personnel à renseigner';}
else if(id==='contact'){content.innerHTML='<div class="plain-page"><span class="eyebrow">C:\\PORTFOLIO\\CONTACT</span><h1>Gardons le contact.</h1><p>Pour discuter d’un projet, de code ou d’une collaboration.</p><div class="contact-fields"><p><b>E-mail :</b> à renseigner</p><p><b>GitHub :</b> à renseigner</p><p><b>LinkedIn :</b> à renseigner</p></div><p>Les liens seront activés lorsque les coordonnées seront ajoutées.</p></div>';status.textContent='Aucun message envoyé depuis cette application';}
else if(id==='terminal')initTerminal(content,state);
else if(id==='paint')initPaint(content,state);
else if(id==='mines')initMines(content,state);
else if(id==='settings'){content.innerHTML=`<div class="settings-page"><h2>Arrière-plan du bureau</h2><div class="settings-preview">Portfolio 95 — Personal Edition</div><div class="swatches">${[['#008080','Classique'],['#000080','Bleu nuit'],['#525252','Graphite'],['#38654a','Vert forêt']].map(([c,n])=>`<button data-color="${c}"><span style="background:${c}"></span>${n}</button>`).join('')}</div><h2>Sons du système</h2><button id="settings-sound">${sounds?'Désactiver':'Activer'} les sons</button><p>Le fond choisi est conservé sur cet appareil. Les sons sont désactivés au démarrage.</p></div>`;content.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>setTheme(b.dataset.color));content.querySelector('#settings-sound').onclick=()=>{$('#audio').click();content.querySelector('#settings-sound').textContent=(sounds?'Désactiver':'Activer')+' les sons'};status.textContent='Affichage · Bureau Windows 95';}
else if(id==='bin'){content.innerHTML=`<div class="recycle">${icon('bin')}<h2>La corbeille est vide.</h2><p>Les bugs ont pris une pause.<br>Profite du calme.</p><small>Aucun fichier personnel n’est stocké ici.</small></div>`;status.textContent='0 objet';}}
function addMenu(state,label,action){state.fileActions.push([label,action])}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function initTerminal(content,state){content.innerHTML='<div class="terminal"><div class="terminal-output"></div><form class="terminal-form"><label for="command">C:\\PORTFOLIO&gt;</label><input id="command" aria-label="Commande du terminal" autocomplete="off" spellcheck="false"></form></div>';const output=content.querySelector('.terminal-output'),input=content.querySelector('input'),terminal=content.querySelector('.terminal'),write=text=>{output.textContent+=text+'\n';terminal.scrollTop=terminal.scrollHeight};write('Portfolio 95 [version 1.0]\nBienvenue. Tape « help » pour les commandes.\n');const history=[];let cursor=0;content.querySelector('form').onsubmit=e=>{e.preventDefault();const command=input.value.trim();input.value='';if(!command)return;history.push(command);cursor=history.length;write('C:\\PORTFOLIO> '+command);switch(command.toLowerCase()){case 'help':write('help      Liste des commandes\nprojects  Ouvrir mes projets\nabout     Ouvrir ma présentation\ncontact   Ouvrir les coordonnées\npaint     Lancer Paint\ngame      Lancer le Démineur\ndate      Date et heure de Paris\nwhoami    Qui se trouve derrière ce bureau\nuname     Informations sur le bureau\nsecret    Une petite surprise\nclear     Effacer le terminal');break;case 'projects':case 'about':case 'contact':case 'paint':openApp(command.toLowerCase());write('Application ouverte.');break;case 'game':openApp('mines');write('Bonne chance !');break;case 'date':write(new Date().toLocaleString('fr-FR',{timeZone:'Europe/Paris'}));break;case 'whoami':write('Un développeur. Le parcours détaillé arrive bientôt.');break;case 'uname':write('Portfolio 95 / Personal Edition\nUn bureau rétro dans ton navigateur.');break;case 'secret':write('Tu as trouvé la porte dérobée :\n↑ ↑ ↓ ↓ ← → ← → B A\nEssaie cette séquence sur le bureau.');break;case 'clear':output.textContent='';break;default:write(`Commande inconnue : ${command}\nTape « help » pour voir les commandes.`)}write('')};input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();cursor=Math.max(0,cursor-1);input.value=history[cursor]||''}if(e.key==='ArrowDown'){e.preventDefault();cursor=Math.min(history.length,cursor+1);input.value=history[cursor]||''}});state.el.querySelector('.statusbar').textContent='Commandes du portfolio uniquement · help pour commencer';setTimeout(()=>input.focus(),50)}
function initPaint(content,state){content.innerHTML='<div class="paint-content"><div class="paint-tools"><label>Outil <select id="paint-tool"><option value="draw">Crayon</option><option value="erase">Gomme</option></select></label><label>Taille <select id="paint-size"><option value="2">2 px</option><option value="5" selected>5 px</option><option value="12">12 px</option><option value="24">24 px</option></select></label><button id="paint-clear">Nouveau</button><button id="paint-save">Enregistrer .png</button></div><div class="paint-area"><canvas width="900" height="450" aria-label="Zone de dessin Paint"></canvas></div><div class="palette" aria-label="Couleurs du crayon"></div></div>';const canvas=content.querySelector('canvas'),ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,900,450);let color='#000',drawing=false,last=null;const colors=['#000','#808080','#800000','#808000','#008000','#008080','#000080','#800080','#fff','#c0c0c0','#f00','#ff0','#0f0','#0ff','#00f','#f0f'];colors.forEach(c=>{const b=document.createElement('button');b.style.background=c;b.setAttribute('aria-label','Couleur '+c);b.setAttribute('aria-pressed',c===color);b.onclick=()=>{color=c;content.querySelectorAll('.palette button').forEach(x=>x.setAttribute('aria-pressed',x===b))};content.querySelector('.palette').append(b)});const point=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height]},draw=p=>{ctx.strokeStyle=content.querySelector('#paint-tool').value==='erase'?'#fff':color;ctx.lineWidth=Number(content.querySelector('#paint-size').value);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(...last);ctx.lineTo(...p);ctx.stroke();last=p};canvas.onpointerdown=e=>{drawing=true;last=point(e);canvas.setPointerCapture(e.pointerId);draw([last[0]+.01,last[1]+.01])};canvas.onpointermove=e=>{if(drawing)draw(point(e))};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;content.querySelector('#paint-clear').onclick=()=>systemMessage('Effacer ce dessin et commencer une nouvelle page ?',[['Effacer',()=>{ctx.fillStyle='#fff';ctx.fillRect(0,0,900,450)}],['Annuler',()=>{}]]);content.querySelector('#paint-save').onclick=()=>{const a=document.createElement('a');a.download='mon-dessin.png';a.href=canvas.toDataURL('image/png');a.click()};state.el.querySelector('.statusbar').textContent='Crayon · Dessine à la souris ou au doigt · 900 × 450 px';}
function initMines(content,state){content.innerHTML='<div class="mine-content"><div class="mine-top"><span class="mine-counter" id="mine-count">010</span><button class="mine-restart" aria-label="Nouvelle partie">☺</button><span class="mine-counter" id="mine-time">000</span></div><div class="mine-grid" role="group" aria-label="Grille du démineur, 9 par 9"></div><div class="mine-controls"><button id="flag-mode" aria-pressed="false">Mode drapeau</button><span>10 mines</span></div><p class="mine-info">Clic pour révéler · Clic droit pour poser un drapeau. Le premier clic est toujours sûr.</p></div>';const grid=content.querySelector('.mine-grid');let cells,started,over,flagMode=false,seconds,timer;const buttons=[],neighbors=i=>{const arr=[],x=i%9,y=Math.floor(i/9);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const nx=x+dx,ny=y+dy;if(nx>=0&&nx<9&&ny>=0&&ny<9)arr.push(ny*9+nx)}return arr};
function paint(){let flags=0;cells.forEach((c,i)=>{const b=buttons[i];if(c.flag)flags++;b.className='mine-cell'+(c.open?' revealed':'')+(c.exploded?' exploded':'');b.dataset.n=c.n;b.textContent=c.open?(c.mine?'✹':c.n||''):c.flag?'⚑':'';b.setAttribute('aria-label',`Ligne ${Math.floor(i/9)+1}, colonne ${i%9+1} : ${c.open?(c.mine?'mine':c.n+' mines voisines'):c.flag?'drapeau':'non révélée'}`)});content.querySelector('#mine-count').textContent=String(10-flags).padStart(3,'0')}
function reset(){clearInterval(timer);cells=Array.from({length:81},()=>({mine:false,open:false,flag:false,n:0}));started=over=false;seconds=0;content.querySelector('#mine-time').textContent='000';content.querySelector('.mine-restart').textContent='☺';state.el.querySelector('.statusbar').textContent='Nouvelle partie · 9 × 9 · 10 mines';paint()}
function begin(first){const safe=new Set([first,...neighbors(first)]);let placed=0;while(placed<10){const i=Math.floor(Math.random()*81);if(!safe.has(i)&&!cells[i].mine){cells[i].mine=true;placed++}}cells.forEach((c,i)=>c.n=neighbors(i).filter(n=>cells[n].mine).length);started=true;timer=setInterval(()=>{seconds=Math.min(999,seconds+1);content.querySelector('#mine-time').textContent=String(seconds).padStart(3,'0')},1000)}
function toggleFlag(i){if(over||cells[i].open)return;cells[i].flag=!cells[i].flag;paint()}
function reveal(i){if(over||cells[i].open||cells[i].flag)return;if(!started)begin(i);if(cells[i].mine){cells[i].exploded=true;cells.forEach(c=>{if(c.mine)c.open=true});over=true;clearInterval(timer);content.querySelector('.mine-restart').textContent='☹';state.el.querySelector('.statusbar').textContent='Perdu ! Clique sur le visage pour réessayer.';beep(170);paint();return}const pending=[i];while(pending.length){const n=pending.pop(),c=cells[n];if(c.open||c.flag||c.mine)continue;c.open=true;if(c.n===0)pending.push(...neighbors(n))}if(cells.filter(c=>c.open).length===71){over=true;clearInterval(timer);cells.forEach(c=>{if(c.mine)c.flag=true});content.querySelector('.mine-restart').textContent='☻';state.el.querySelector('.statusbar').textContent='Bravo ! Toutes les mines sont identifiées.';beep(900)}paint()}
for(let i=0;i<81;i++){const b=document.createElement('button');b.className='mine-cell';b.onclick=()=>flagMode?toggleFlag(i):reveal(i);b.oncontextmenu=e=>{e.preventDefault();toggleFlag(i)};b.onkeydown=e=>{const shifts={ArrowLeft:-1,ArrowRight:1,ArrowUp:-9,ArrowDown:9};if(e.key in shifts){e.preventDefault();buttons[Math.max(0,Math.min(80,i+shifts[e.key]))].focus()}if(e.key.toLowerCase()==='f'){e.preventDefault();toggleFlag(i)}};buttons.push(b);grid.append(b)}content.querySelector('.mine-restart').onclick=reset;content.querySelector('#flag-mode').onclick=e=>{flagMode=!flagMode;e.currentTarget.setAttribute('aria-pressed',flagMode);e.currentTarget.textContent=flagMode?'Mode révéler':'Mode drapeau'};state.cleanup=()=>clearInterval(timer);reset();}
function setTheme(color){if(!['#008080','#000080','#525252','#38654a'].includes(color))return;document.documentElement.style.setProperty('--desk',color);try{localStorage.setItem('portfolio95.background',color)}catch{}}
try{setTheme(localStorage.getItem('portfolio95.background'))}catch{}
function closeMenus(){menu.hidden=true;$('#start').setAttribute('aria-expanded','false');$('#context').hidden=true;$('#file-menu').hidden=true}
$('#start').onclick=e=>{e.stopPropagation();const opening=menu.hidden;closeMenus();menu.hidden=!opening;$('#start').setAttribute('aria-expanded',opening);if(opening)beep(420)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openApp(b.dataset.open);if(!e.target.closest('#start-menu')&&!e.target.closest('#start')&&!e.target.closest('#file-menu'))closeMenus()});
desktop.addEventListener('pointerdown',e=>{if(!e.target.closest('.window')&&!e.target.closest('.desktop-icon')){selectedIcon?.classList.remove('selected');selectedIcon=null;closeMenus()}});
desktop.addEventListener('contextmenu',e=>{if(e.target.closest('.window'))return;e.preventDefault();closeMenus();const ctx=$('#context');ctx.hidden=false;ctx.style.left=Math.min(e.clientX,innerWidth-ctx.offsetWidth-5)+'px';ctx.style.top=Math.min(e.clientY,desktop.clientHeight-ctx.offsetHeight-5)+'px'});
$('#audio').onclick=()=>{sounds=!sounds;$('#audio').setAttribute('aria-pressed',sounds);$('#audio').setAttribute('aria-label',sounds?'Désactiver les sons':'Activer les sons');$('#audio').textContent=sounds?'♫':'♪';beep(700)};
function systemMessage(message,actions=[['OK',()=>{}]]){const dialog=$('#system-dialog');$('#system-message').textContent=message;$('#system-actions').replaceChildren();actions.forEach(([label,action])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{dialog.close();action()};$('#system-actions').append(b)});if(!dialog.open)dialog.showModal();beep(300)}
$('#dialog-close').onclick=()=>$('#system-dialog').close();
const timeFormatter=new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',hour:'2-digit',minute:'2-digit'});function updateClock(){const time=timeFormatter.format(new Date());$('#clock').textContent=time;$('#clock').title=new Date().toLocaleDateString('fr-FR',{timeZone:'Europe/Paris',weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#sleep-clock').textContent=time}updateClock();setInterval(updateClock,10000);
function sleep(){closeMenus();$('#sleep-screen').hidden=false}function wake(){$('#sleep-screen').hidden=true}$('#sleep').onclick=sleep;$('#sleep-screen').onclick=wake;
$('#shutdown').onclick=()=>{closeMenus();systemMessage('Que voulez-vous faire ?',[['Mettre en veille',sleep],['Redémarrer',()=>{for(const id of [...openWindows.keys()])closeWindow(id);openApp('welcome')}],['Annuler',()=>{}]])};
let sequence=[];const konami=['arrowup','arrowup','arrowdown','arrowdown','arrowleft','arrowright','arrowleft','arrowright','b','a'];document.addEventListener('keydown',e=>{if(!$('#sleep-screen').hidden){wake();e.preventDefault();return}if(e.key==='Escape'){closeMenus();return}if(e.ctrlKey&&e.key==='`'){e.preventDefault();openApp('terminal')}if(e.target.matches('input,textarea,select')||e.target.closest('.mine-grid'))return;sequence.push(e.key.toLowerCase());sequence=sequence.slice(-10);if(sequence.join(',')===konami.join(',')){systemMessage('Niveau secret débloqué. Tu connais tes classiques ! Le Démineur t’attend.',[['Jouer',()=>openApp('mines')],['Fermer',()=>{}]]);sequence=[]}});
let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>openWindows.forEach(({el})=>{if(innerWidth<751)return;el.style.width=Math.min(el.offsetWidth,innerWidth-12)+'px';el.style.height=Math.min(el.offsetHeight,desktop.clientHeight-12)+'px';el.style.left=Math.max(0,Math.min(el.offsetLeft,innerWidth-el.offsetWidth))+'px';el.style.top=Math.max(0,Math.min(el.offsetTop,desktop.clientHeight-el.offsetHeight))+'px'}),100)});
const endBoot=()=>{$('#boot').hidden=true};$('#skip-boot').onclick=endBoot;setTimeout(endBoot,matchMedia('(prefers-reduced-motion:reduce)').matches?0:1100);openApp('welcome');


function showFileMenu(id,anchor){const w=openWindows.get(id);if(!w)return;const fileMenu=$('#file-menu');const same=!fileMenu.hidden&&fileMenu.dataset.window===id;closeMenus();if(same)return;fileMenu.dataset.window=id;fileMenu.replaceChildren();const actions=[...w.fileActions,['Fermer',()=>closeWindow(id)]];actions.forEach(([label,action])=>{const b=document.createElement('button');b.setAttribute('role','menuitem');b.textContent=label;b.onclick=()=>{closeMenus();action()};fileMenu.append(b)});fileMenu.hidden=false;const r=anchor.getBoundingClientRect();fileMenu.style.left=Math.min(r.left,innerWidth-fileMenu.offsetWidth-4)+'px';fileMenu.style.top=Math.min(r.bottom,desktop.clientHeight-fileMenu.offsetHeight-4)+'px';fileMenu.querySelector('button').focus()}
$('#file-menu').addEventListener('keydown',e=>{const items=[...$('#file-menu').querySelectorAll('button')];const i=items.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[(i+(e.key==='ArrowDown'?1:items.length-1))%items.length].focus()}});
